tools.example:
// place LED1..LED12 on a circle of 20 mm radius around (50 50)
string Cmd = "GRID MM;\n";
for (int i = 0; i < 12; ++i) {
    real a = i * 30.0 * PI / 180;
    string c;
    sprintf(c, "MOVE LED%d (%.3f %.3f);\n", i + 1, 50 + 20 * cos(a), 50 + 20 * sin(a));
    Cmd += c;
    }
exit(Cmd);

